import { readFileSync } from "node:fs";

// Reconstruct each lookup's occupancy interval from (completion, duration)
// and measure how much of the run had >1 lookup actually in flight. This is
// a direct observation of whether the pool overlapped work — it needs no
// baseline and is immune to run-to-run upstream latency noise.
const load = (path) =>
  JSON.parse(readFileSync(path, "utf8"))
    .result.map((s) => (typeof s === "string" ? JSON.parse(s) : s))
    .sort((a, b) => a.at - b.at);

function biggestRun(samples) {
  const runs = [];
  let start = 0;
  for (let i = 1; i <= samples.length; i++) {
    if (i !== samples.length && samples[i].at - samples[i - 1].at <= 60_000)
      continue;
    runs.push(samples.slice(start, i));
    start = i;
  }
  return runs.sort((a, b) => b.length - a.length)[0];
}

function analyze(label, run) {
  const events = [];
  for (const s of run) {
    events.push([s.at - s.ms, +1]);
    events.push([s.at, -1]);
  }
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const timeAt = new Map(); // concurrency level -> ms spent there
  let cur = 0;
  let prev = events[0][0];
  let peak = 0;
  for (const [t, d] of events) {
    if (t > prev) timeAt.set(cur, (timeAt.get(cur) ?? 0) + (t - prev));
    cur += d;
    peak = Math.max(peak, cur);
    prev = t;
  }

  const span = run[run.length - 1].at - (run[0].at - run[0].ms);
  const busy = [...timeAt.entries()]
    .filter(([k]) => k > 0)
    .reduce((a, [, v]) => a + v, 0);
  const idle = timeAt.get(0) ?? 0;
  const busyMs = run.reduce((a, s) => a + s.ms, 0);

  console.log(`\n=== ${label} ===`);
  console.log(`  span ${(span / 1000).toFixed(0)}s, ${run.length} lookups`);
  console.log(`  peak concurrency observed: ${peak}`);
  console.log(`  mean concurrency while busy: ${(busyMs / busy).toFixed(2)}`);
  console.log(
    `  DEAD TIME (0 lookups in flight): ${(idle / 1000).toFixed(0)}s = ${((idle / span) * 100).toFixed(0)}% of the run`,
  );
  for (const k of [...timeAt.keys()].sort((a, b) => a - b)) {
    const pctT = ((timeAt.get(k) / span) * 100).toFixed(0);
    if (+pctT === 0) continue;
    console.log(
      `    ${k} in flight: ${(timeAt.get(k) / 1000).toFixed(0)}s (${pctT}%)`,
    );
  }
}

analyze("BEFORE (sequential)", biggestRun(load(process.argv[2])));
analyze("AFTER (pool of 4)", biggestRun(load(process.argv[3])));

